import * as React from 'react';
import { cva, type VariantProps } from 'class-variance-authority';
import { cn } from 'cn';
import { Slot } from 'radix-ui';

// DevMentor button (generated by shadcn, adapted in stage 2; decisions in packages/ui/POSTEP.md).
// Shape: 6 px radius (A01), no shadow (R01.1). Focus: 2 px --ring outline, 2 px offset (WCAG 2.4.7, 2.4.13).
// Motion: colour and border only, --motion-fast; off under reduced motion (globals.css).
const buttonVariants = cva(
  "inline-flex shrink-0 items-center justify-center gap-inline rounded-lg border border-transparent text-base font-medium whitespace-nowrap transition-colors duration-(--motion-fast) focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-solid focus-visible:outline-ring disabled:pointer-events-none [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
  {
    variants: {
      variant: {
        // R01.5 + K2: the one primary action per screen
        default:
          'bg-primary text-primary-foreground hover:bg-primary-hover active:bg-primary-hover disabled:bg-muted disabled:text-muted-foreground',
        // R01.5: other actions are neutral
        secondary:
          'bg-secondary text-secondary-foreground hover:bg-accent hover:text-accent-foreground active:bg-accent disabled:text-muted-foreground',
        // tokeny.md: an interactive element bounded only by a line uses --border-strong (WCAG 1.4.11)
        outline:
          'border-border-strong bg-card text-foreground hover:bg-accent hover:text-accent-foreground active:bg-accent disabled:border-border disabled:bg-muted disabled:text-muted-foreground',
        ghost:
          'text-foreground hover:bg-accent hover:text-accent-foreground active:bg-accent disabled:text-muted-foreground',
        // R01.3: decline and cancel; hover = --destructive-hover (K2 by analogy to --primary-hover; default accepted 2026-10-24)
        destructive:
          'bg-destructive text-destructive-foreground hover:bg-destructive-hover active:bg-destructive-hover disabled:bg-muted disabled:text-muted-foreground',
        // WCAG 1.4.1: a link is always underlined, not only on hover (stage 2 decision 4)
        link: 'min-h-6 text-primary underline underline-offset-4 hover:text-primary-hover active:text-primary-hover disabled:text-muted-foreground',
      },
      size: {
        default: 'h-control px-4 has-[>svg]:px-3',
        sm: 'h-control-sm px-3 has-[>svg]:px-2',
        icon: 'size-control',
        'icon-sm': 'size-control-sm',
      },
    },
    defaultVariants: {
      variant: 'default',
      size: 'default',
    },
  },
);

type ButtonProps = React.ComponentProps<'button'> &
  VariantProps<typeof buttonVariants> & {
    /** Render the child element (e.g. `<a>`) with button styles instead of a `<button>`. */
    asChild?: boolean;
  };

function Button({ className, variant = 'default', size = 'default', asChild = false, ...props }: ButtonProps) {
  const Comp = asChild ? Slot.Root : 'button';
  // A link is text in a line: it takes no control height or padding.
  const appliedSize = variant === 'link' ? null : size;

  return (
    <Comp
      data-slot="button"
      data-variant={variant}
      data-size={appliedSize ?? undefined}
      className={cn(buttonVariants({ variant, size: appliedSize, className }))}
      {...props}
    />
  );
}

export { Button, buttonVariants, type ButtonProps };
